INSERT INTO `wp_aioseo_cache` VALUES (5,NULL,'{\"wp_actionscheduler_actions\":[\"action_id\",\"args\",\"attempts\",\"claim_id\",\"extended_args\",\"group_id\",\"hook\",\"last_attempt_gmt\",\"last_attempt_local\",\"priority\",\"schedule\",\"scheduled_date_gmt\",\"scheduled_date_local\",\"status\"],\"wp_actionscheduler_claims\":[\"claim_id\",\"date_created_gmt\"],\"wp_actionscheduler_groups\":[\"group_id\",\"slug\"],\"wp_actionscheduler_logs\":[\"action_id\",\"log_date_gmt\",\"log_date_local\",\"log_id\",\"message\"],\"wp_aioseo_ai_insights_keyword_reports\":[\"brands\",\"brands_mentioned\",\"created\",\"id\",\"keyword\",\"results\",\"status\",\"updated\",\"uuid\"],\"wp_aioseo_cache\":[\"created\",\"expiration\",\"id\",\"is_object\",\"key\",\"name\",\"updated\",\"value\"],\"wp_aioseo_crawl_cleanup_blocked_args\":[\"created\",\"hits\",\"id\",\"key\",\"key_value_hash\",\"param\",\"param_value_hash\",\"regex\",\"updated\",\"value\"],\"wp_aioseo_crawl_cleanup_logs\":[\"created\",\"hash\",\"hits\",\"id\",\"key\",\"param\",\"slug\",\"updated\",\"value\"],\"wp_aioseo_notifications\":[\"addon\",\"button1_action\",\"button1_label\",\"button2_action\",\"button2_label\",\"content\",\"created\",\"dismissed\",\"end\",\"id\",\"level\",\"new\",\"notification_id\",\"notification_name\",\"slug\",\"start\",\"title\",\"type\",\"updated\"],\"wp_aioseo_posts\":[\"additional_keywords\",\"ai\",\"breadcrumb_settings\",\"canonical_url\",\"created\",\"description\",\"focus_keyword\",\"frequency\",\"id\",\"image_scan_date\",\"images\",\"keyphrases\",\"keywords\",\"limit_modified_date\",\"local_seo\",\"og_article_section\",\"og_article_tags\",\"og_custom_url\",\"og_description\",\"og_image_custom_fields\",\"og_image_custom_url\",\"og_image_height\",\"og_image_type\",\"og_image_url\",\"og_image_width\",\"og_object_type\",\"og_title\",\"og_video\",\"options\",\"page_analysis\",\"pillar_content\",\"post_id\",\"primary_term\",\"priority\",\"robots_default\",\"robots_max_imagepreview\",\"robots_max_snippet\",\"robots_max_videopreview\",\"robots_noarchive\",\"robots_nofollow\",\"robots_noimageindex\",\"robots_noindex\",\"robots_noodp\",\"robots_nosnippet\",\"robots_notranslate\",\"schema\",\"schema_type\",\"schema_type_options\",\"seo_analyzer_scan_date\",\"seo_score\",\"title\",\"truseo\",\"truseo_locale\",\"twitter_card\",\"twitter_description\",\"twitter_image_custom_fields\",\"twitter_image_custom_url\",\"twitter_image_type\",\"twitter_image_url\",\"twitter_title\",\"twitter_use_og\",\"updated\",\"video_scan_date\",\"video_thumbnail\",\"videos\"],\"wp_aioseo_seo_analyzer_results\":[\"competitor_url\",\"created\",\"data\",\"id\",\"score\",\"updated\"],\"wp_aioseo_writing_assistant_keywords\":[\"competitors\",\"country\",\"created\",\"id\",\"keyword\",\"keywords\",\"language\",\"progress\",\"updated\",\"uuid\"],\"wp_aioseo_writing_assistant_posts\":[\"content_analysis\",\"content_analysis_hash\",\"created\",\"id\",\"keyword_id\",\"post_id\",\"updated\"]}',0,'2026-10-21 05:16:43','2026-10-09 10:02:08','2026-10-20 05:16:43','db_schema'),(3,NULL,'[{\"sku\":\"aioseo-redirects\",\"name\":\"Redirection Manager\",\"version\":\"1.4.15\",\"image\":null,\"icon\":\"\",\"levels\":[\"business\",\"agency\",\"pro\",\"elite\"],\"currentLevels\":[\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Our Redirection Manager allows you to create and manage redirects for 404s or modified posts.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/features\\/redirection-manager\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/features\\/redirection-manager\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-redirects:redirects\",\"features\":[{\"license_level\":\"elite\",\"feature\":\"404-parent-redirect\"}]},{\"sku\":\"aioseo-link-assistant\",\"name\":\"Link Assistant\",\"version\":\"1.1.19\",\"image\":null,\"icon\":\"\",\"levels\":[\"agency\",\"pro\",\"elite\"],\"currentLevels\":[\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Super-charge your SEO with Link Assistant! Get relevant suggestions for adding internal links to older content as well as finding any orphaned posts that have no internal links. Use our reporting feature to see all link suggestions or add them directly from any page or post.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/docs\\/link-assistant\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/docs\\/link-assistant\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-link-assistant:overview\",\"features\":[]},{\"sku\":\"aioseo-video-sitemap\",\"name\":\"Video Sitemap\",\"version\":\"1.1.28\",\"image\":null,\"icon\":\"\",\"levels\":[\"individual\",\"business\",\"agency\",\"pro\",\"elite\"],\"currentLevels\":[\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>The Video Sitemap works in much the same way as the XML Sitemap module, it generates an XML Sitemap specifically for video content on your site. Search engines use this information to display rich snippet information in search results.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/docs\\/how-to-create-a-video-sitemap\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/docs\\/how-to-create-a-video-sitemap\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-sitemaps:video-sitemap\",\"features\":[]},{\"sku\":\"aioseo-local-business\",\"name\":\"Local Business SEO\",\"version\":\"1.3.17\",\"image\":null,\"icon\":\"svg-local-business\",\"levels\":[\"business\",\"agency\",\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Local Business schema markup enables you to tell Google about your business, including your business name, address and phone number, opening hours and price range. This information may be displayed as a Knowledge Graph card or business carousel.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/docs\\/local-business-seo\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/docs\\/local-business-seo\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-local-seo:locations\",\"features\":[]},{\"sku\":\"aioseo-news-sitemap\",\"name\":\"News Sitemap\",\"version\":\"1.0.22\",\"image\":null,\"icon\":\"svg-sitemaps-pro\",\"levels\":[\"business\",\"agency\",\"pro\",\"elite\"],\"currentLevels\":[\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Our Google News Sitemap lets you control which content you submit to Google News and only contains articles that were published in the last 48 hours. In order to submit a News Sitemap to Google, you must have added your site to Google\\u2019s Publisher Center and had it approved.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/docs\\/how-to-create-a-google-news-sitemap\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/docs\\/how-to-create-a-google-news-sitemap\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-sitemaps:news-sitemap\",\"features\":[]},{\"sku\":\"aioseo-index-now\",\"name\":\"IndexNow\",\"version\":\"1.0.15\",\"image\":null,\"icon\":\"\",\"levels\":[\"business\",\"agency\",\"basic\",\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"basic\",\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Add IndexNow support to instantly notify search engines when your content has changed. This helps the search engines to prioritize the changes on your website and helps you rank faster.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/index-now\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/index-now\",\"manageUrl\":\"https:\\/\\/route#aioseo-settings:webmaster-tools\",\"features\":[]},{\"sku\":\"aioseo-rest-api\",\"name\":\"REST API\",\"version\":\"1.0.9\",\"image\":null,\"icon\":\"PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHZpZXdCb3g9IjAgMCAyNCAyNCIgY2xhc3M9ImFpb3Nlby1jb2RlIj48cGF0aCBkPSJNOS40IDE2LjZMNC44IDEybDQuNi00LjZMOCA2bC02IDYgNiA2IDEuNC0xLjR6bTUuMiAwbDQuNi00LjYtNC42LTQuNkwxNiA2bDYgNi02IDYtMS40LTEuNHoiIGZpbGw9ImN1cnJlbnRDb2xvciIvPjwvc3ZnPg==\",\"levels\":[\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Manage your post and term SEO meta via the WordPress REST API. This addon also works seamlessly with headless WordPress installs.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/feature\\/rest-api\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/feature\\/rest-api\\/\",\"manageUrl\":\"\",\"features\":[]},{\"sku\":\"aioseo-image-seo\",\"name\":\"Image SEO\",\"version\":\"1.2.8\",\"image\":null,\"icon\":\"\",\"levels\":[\"business\",\"agency\",\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Globally control the Title, Alt Text, Caption and Descriptions for images in your content. These attributes are essential for both accessibility and SEO.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/docs\\/using-the-image-seo-features-in-all-in-one-seo\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/docs\\/using-the-image-seo-features-in-all-in-one-seo\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-search-appearance:media\",\"features\":[]},{\"sku\":\"aioseo-eeat\",\"name\":\"Author SEO (E-E-A-T)\",\"version\":\"1.2.16\",\"image\":null,\"icon\":\"\",\"levels\":[\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Optimize your site for Google\'s E-E-A-T ranking factor by proving your writer\'s expertise through author schema markup and new UI elements.<\\/p>\\n\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/features\\/eeat\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/features\\/eeat\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-search-appearance:author-seo\",\"features\":[]}]',0,'2026-10-21 05:16:43','2026-10-09 00:08:37','2026-10-20 05:16:43','addons'),(4,NULL,'\"none\"',0,'2026-10-20 05:16:41','2026-10-09 01:43:19','2026-10-19 05:16:41','attachment_url_to_post_id_d99ed2ddbeefba28910cca4100f73b401b38bc49'),(6,NULL,'[]',0,'2026-10-21 05:51:46','2026-10-09 10:16:48','2026-10-20 05:51:46','wp_notices'),(9,NULL,'[{\"id\":1110156,\"title\":\"TruSEO for Taxonomies: Get SEO Scores for Your Category Pages\",\"excerpt\":\"Category pages, tag archives, and custom taxonomy pages are some of the most visited pages on WordPress sites. And until now, it was nearly impossible to see how well they were optimized. That changes with AIOSEO 5.0.1. TruSEO now works\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/truseo-for-taxonomies\\/\",\"date\":\"2026-08-26T05:27:21+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.1.\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/08\\/truseo-for-taxonomies-featured-300x167.png\",\"callout\":[]},{\"id\":1085667,\"title\":\"Introducing TruSEO 2.0: Real-Time Scoring, New Look, 10+ Languages\",\"excerpt\":\"TruSEO 2.0 is the biggest rebuild TruSEO has ever gotten: real-time scoring, 10+ new languages with per-post control, and a redesigned Optimization tab that finally organizes your score into clear sections.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-truseo-2-0\\/\",\"date\":\"2026-07-30T19:43:36+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/introducing-truseo-20-1-300x167.png\",\"callout\":[]},{\"id\":1085275,\"title\":\"Rewrite Your WordPress Post for Search in 1 Click With AI\",\"excerpt\":\"TruSEO can now rewrite your SEO title, meta description, and content, and fix spelling, all in 1 click.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/optimize-with-ai\\/\",\"date\":\"2026-07-30T19:42:38+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/optimize-with-ai-announcement-1-300x167.png\",\"callout\":[]},{\"id\":1084326,\"title\":\"Introducing Spell Checker: Catch Typos Before You Publish\",\"excerpt\":\"AIOSEO 5.0.0 introduces a built-in Spell Checker that flags and fixes misspelled words with one click. Custom dictionary and language settings available on all plans.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-spell-checker\\/\",\"date\":\"2026-07-30T19:42:11+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/wordpress-spell-checker-aioseo-300x167.png\",\"callout\":[]},{\"id\":1081420,\"title\":\"TruSEO Highlighter Now Suggests & Applies AI-Powered Fixes\",\"excerpt\":\"AIOSEO 5.0.0 upgrades the TruSEO Highlighter with AI-powered fix suggestions. Click a highlighted issue and apply an AI-generated fix right there in the editor, no more tabbing back and forth to fix what\'s flagged. It\'s included on every plan, Basic through Elite.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/truseo-highlighter-suggests-fixes\\/\",\"date\":\"2026-07-30T19:41:05+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/truseo-highlighter-ai-fixes-1-300x167.png\",\"callout\":[]},{\"id\":1083285,\"title\":\"The Headline Analyzer Now Lives Inside Your SEO Score\",\"excerpt\":\"AIOSEO 5.0.0 moves the Headline Analyzer inside your TruSEO score. Edit your headline and watch the score update instantly, then compare versions before you pick a winner.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/headline-analyzer-in-truseo\\/\",\"date\":\"2026-07-30T19:40:22+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"5.0.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/07\\/headline-analyzer-announcement-1-300x167.png\",\"callout\":[]},{\"id\":1053472,\"title\":\"Event & Job Posting Schema Now Available on All AIOSEO Plans\",\"excerpt\":\"If you run events or post job listings, here\'s how to use event and job posting schema to unlock rich results in Google.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/event-job-posting-schema-basic\\/\",\"date\":\"2026-07-13T09:27:15+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.9\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/Event-Job-Posting-Schema-Announcement-2-300x167.png\",\"callout\":[]},{\"id\":1053146,\"title\":\"Meet SEO Alerts: An Early Warning System for Critical Site Issues\",\"excerpt\":\"Most serious SEO problems don\\u2019t announce themselves. You find out the way no one wants to: traffic starts sliding, someone asks why, and you spend an afternoon working backwards trying to figure out what changed. I\\u2019ve seen sites go weeks\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-seo-alerts\\/\",\"date\":\"2026-07-08T10:35:07+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.9\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/wordpress-seo-alerts-300x167.png\",\"callout\":[]},{\"id\":1039047,\"title\":\"Introducing AIOSEO MCP: Your AI Agents Can Now Work on Your WordPress SEO\",\"excerpt\":\"AIOSEO 4.9.8 introduces MCP support, letting you connect Claude, Cursor, ChatGPT, and other AI agents directly to your WordPress site. Ask your AI to fix your SEO\\u2014 and it actually does it, right from chat. Free for every plan, including Lite.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-aioseo-mcp\\/\",\"date\":\"2026-06-17T11:02:42+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/aioseo-mcp-featured-300x167.png\",\"callout\":[]},{\"id\":1044143,\"title\":\"Meet GPT Image 2 & Nano Banana 2, Now Built Into AIOSEO\",\"excerpt\":\"AIOSEO 4.9.8 adds 2 new models to the AI Image Generator: GPT Image 2 from OpenAI and Nano Banana 2 from Google, giving you more creative freedom than ever to produce unique images for your WordPress site.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/gpt-image-2-nano-banana-2\\/\",\"date\":\"2026-06-17T10:34:12+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/gpt-image-2-nano-banana-2-aioseo-300x167.png\",\"callout\":[]},{\"id\":1043366,\"title\":\"AIOSEO REST API Is Now Free for All Users, Including Lite\",\"excerpt\":\"Starting with AIOSEO 4.9.8, the REST API is free for every plan, including Lite. The addon is deprecated and merged into core, giving all users full programmatic access to their SEO data over HTTP, no upgrade required.\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-rest-api\\/\",\"date\":\"2026-06-17T10:33:38+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/06\\/REST-API-Now-Free-Featured-Image-Green--300x167.png\",\"callout\":[]},{\"id\":987541,\"title\":\"Generate Schema Markup in Seconds With AI\",\"excerpt\":\"The concept of schema markup is simple. The execution of it is not. But you know it matters. You\\u2019ve seen the star ratings, cooking times, and FAQs that dominate the search results when a site has it. Unfortunately, getting there\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-6-release\\/\",\"date\":\"2026-04-22T13:15:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.6\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/04\\/aioseo-4-9-6-300x167.png\",\"callout\":[]},{\"id\":893135,\"title\":\"Introducing the SEO Checklist & AI Suite\",\"excerpt\":\"Have you ever finished setting up a plugin and thought, \\u201cOkay, I\\u2019m done with the wizard\\u2026 now what?\\u201d I know the feeling. You want to make sure you\\u2019re getting the most out of your new tool, but with so many\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-4-release\\/\",\"date\":\"2026-02-24T14:15:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.4\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2026\\/02\\/aioseo-4-9-4-300x167.png\",\"callout\":[]},{\"id\":809457,\"title\":\"AI Keyword Report & Redirects for More Plans\",\"excerpt\":\"Want to know who\\u2019s ranking in AI search results? Me too. That\\u2019s why our developers have been working hard to create a tool that both our internal team\\u2014and you\\u2014can use. With AIOSEO 4.9.1, you get a powerful new Keyword Report\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-1-release\\/\",\"date\":\"2025-12-16T14:35:52+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.1\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/12\\/aioseo-491-ai-keyword-report-300x171.png\",\"callout\":[]},{\"id\":784513,\"title\":\"Smarter Blocks for Recipes, Products, & Navigation\",\"excerpt\":\"Get ready to transform your website with AIOSEO 4.9.0! This update has one of our most requested features\\u2014a fully-optimized Recipe block\\u2014along with an all-new Product block and a revamp of our much-loved Table of Contents. Whether you\\u2019re sharing recipes, showcasing\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-9-0-release\\/\",\"date\":\"2025-11-27T15:03:47+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.9.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/11\\/aioseo-4-9-0-300x171.png\",\"callout\":[]},{\"id\":742955,\"title\":\"Unleash the Power of AI for Your Website!\",\"excerpt\":\"Today, I\\u2019m thrilled to announce the release of AIOSEO 4.8.8\\u2014our most ambitious and transformative update yet! We\\u2019re bringing the power of AI directly to your fingertips, so you can create, design, and optimize your content faster and smarter than ever\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/aioseo-4-8-8-release\\/\",\"date\":\"2025-10-23T13:15:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/10\\/aioseo-488-ai-300x167.png\",\"callout\":[]},{\"id\":691425,\"title\":\"Site Audit for Simplified SEO Diagnostics\",\"excerpt\":\"Tired of guessing why your website isn\\u2019t ranking higher? Do you struggle to pinpoint the exact SEO issues holding you back? This often leads to wasted time, missed opportunities, and frustration. Imagine knowing exactly which pages need attention to drive\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/site-audit-announcement\\/\",\"date\":\"2025-08-26T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.6\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/08\\/seo-audit-2-300x167.png\",\"callout\":[]},{\"id\":639640,\"title\":\"AI Content Generator: Supercharge Your Content Creation!\",\"excerpt\":\"Tired of spending hours crafting content, only to struggle with SEO titles, meta descriptions, social media posts, and FAQs? A common challenge many publishers face is creating high-quality, SEO-optimized content. From writing engaging articles to generating effective meta descriptions and\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-ai-content-generator\\/\",\"date\":\"2025-07-08T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.4\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/07\\/ai-content-generator-1-300x167.png\",\"callout\":[]},{\"id\":589447,\"title\":\"Index Status Report: Get Indexing Data Right Inside WordPress\",\"excerpt\":\"Are you absolutely certain Google is indexing all your content? Here\\u2019s a shocking truth\\u2014a significant portion of your WordPress website could be invisible to Google due to indexing issues. We\\u2019re talking about the majority of your pages and posts not\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-index-status-report\\/\",\"date\":\"2025-05-20T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.2\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/05\\/introducing-index-status-report-300x167.png\",\"callout\":[]},{\"id\":532688,\"title\":\"Unlock Better SEO Performance: Introducing AIOSEO 4.8.0\'s Advanced Crawl Features\",\"excerpt\":\"We\\u2019re back with another powerful update! AIOSEO 4.8.0 is here, and I\\u2019m so excited to introduce advanced tools to fine-tune your website\\u2019s crawlability, prevent unwanted indexing, and improve performance. Let\\u2019s dive into what\\u2019s new. In This Article Crawl Cleanup Supercharged\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/introducing-aioseo-4-8-0-advanced-crawl-features\\/\",\"date\":\"2025-03-11T13:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.8.0\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/03\\/announcement-crawl-features-300x167.png\",\"callout\":[]},{\"id\":492479,\"title\":\"Smarter Keyword Rank Tracking & WooCommerce SEO Made Easy!\",\"excerpt\":\"Big news! We\\u2019ve just released AIOSEO 4.7.8, and it\\u2019s loaded with exciting updates you\\u2019re going to love. These enhancements will help you take your SEO game to the next level! Let\\u2019s break it down\\u2026 In This Article Keyword Rank Tracker\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/smarter-keyword-rank-tracking-woocommerce-seo-made-easy\\/\",\"date\":\"2025-01-28T14:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.7.8\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2025\\/01\\/annoucement-krt-woocommerce-seo-300x167.png\",\"callout\":[]},{\"id\":458400,\"title\":\"BuddyPress & Web Stories Integrations + Author SEO Upgrades!\",\"excerpt\":\"We\\u2019ve rolled out several updates and new features this year. And we\\u2019re back with many more new features to help you take your SEO to a whole new level! The top 3 we\\u2019re most excited about are the: With these\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/new-aioseo-4-7-6-buddypress-web-stories-integration-author-seo-improvements\\/\",\"date\":\"2024-12-12T14:30:00+00:00\",\"product\":\"aioseo\",\"label\":\"AIOSEO\",\"badge\":\"aioseo\",\"version\":\"4.7.6\",\"screens\":[],\"image\":\"https:\\/\\/aioseo.com\\/wp-content\\/uploads\\/2024\\/12\\/buddypress-google-web-stories-author-seo-300x167.png\",\"callout\":[]},{\"id\":424835,\"title\":\"Revolutionize Your Content Creation with AIOSEO\'s Writing Assistant\",\"excerpt\":\"We\\u2019ve just released version 4.7.4 of AIOSEO, and we\\u2019re beyond excited to unveil a game-changing feature that will completely transform how you create optimized content in WordPress. We call it Writing Assistant! Imagine having a personal assistant by your side,\\u2026\",\"url\":\"https:\\/\\/aioseo.com\\/newsroom\\/