  `focus_keyword` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `truseo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci,
  `additional_keywords` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci,
  `truseo_locale` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ndx_aioseo_posts_post_id` (`post_id`),
  KEY `ndx_aioseo_posts_pillar_content` (`pillar_content`),
  KEY `ndx_aioseo_posts_focus_keyword` (`focus_keyword`(250))
) ENGINE=MyISAM AUTO_INCREMENT=238 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
